const ShiftBadge = memo(({ shift, times }) => {
    let key = 'Libur';
    if (shift === 'Pagi') key = 'Pagi';
    else if (shift === 'Siang' || shift === 'Sore') key = 'Siang';
    else if (shift === 'Malam') key = 'Malam';

    const style = SHIFT_STYLE[key];
    const time = key === 'Pagi' ? times.pagi
        : key === 'Siang' ? (times.siang || times.sore)
        : key === 'Malam' ? times.malam
        : times.libur;

    return (
        <div className="flex flex-col items-center gap-1">
            <span className={`inline-flex items-center gap-1 whitespace-nowrap px-2.5 py-1 rounded-full border text-[11px] font-semibold ${style.pill}`}>
                <Icon name={style.icon} className="w-3 h-3" />
                {style.label}
            </span>
            <span className="text-[10px] text-slate-400 font-medium leading-tight">{time}</span>
        </div>
    );
});

