    const handleSendJadwalToTelegram = async () => {
        if (!jadwalContainerRef.current) {
            showToast("Elemen jadwal tidak ditemukan!", "error");
            return;
        }

        const cleanBotToken = TELEGRAM_BOT_TOKEN.trim();
        const cleanChatId = TELEGRAM_CHAT_ID.trim();

        if (!cleanBotToken || !cleanChatId) {
            showToast("Bot Token / Chat ID belum diatur dengan benar!", "error");
            return;
        }

        try {
            setIsSendingTelegram(true);
            showToast("Mempersiapkan gambar jadwal utuh...", "warning");

            let html2canvas;
            try {
                html2canvas = (await import('html2canvas')).default;
            } catch (err) {
                console.error("html2canvas belum diinstall:", err);
                showToast("Sistem membutuhkan library 'html2canvas'. Jalankan `npm install html2canvas`", "error");
                setIsSendingTelegram(false);
                return;
            }

            const element = jadwalContainerRef.current;

            const canvas = await html2canvas(element, {
                scale: 2,
                useCORS: true,
                backgroundColor: "#ffffff",
                scrollX: 0,
                scrollY: 0,
                windowWidth: 1400,
                ignoreElements: (el) => el.classList.contains('no-export'),
                onclone: (clonedDoc) => {
                    const dateInputs = clonedDoc.querySelectorAll('.date-header-input');
                    dateInputs.forEach((input) => {
                        const val = input.value || input.placeholder || '';
                        const textSpan = clonedDoc.createElement('span');
                        textSpan.innerText = val;
                        textSpan.className = "text-blue-200 font-mono text-xs font-bold block text-center mt-1";
                        if (input.parentNode) {
                            input.parentNode.replaceChild(textSpan, input);
                        }
                    });
                }
            });

            canvas.toBlob(async (blob) => {
                if (!blob) {
                    showToast("Gagal membuat file gambar", "error");
                    setIsSendingTelegram(false);
                    return;
                }

                const formDataToSend = new FormData();
                formDataToSend.append("chat_id", cleanChatId);
                formDataToSend.append("photo", blob, "jadwal_kerja.png");
                formDataToSend.append("caption", `📅 JADWAL KERJA STAFF TERBARU\nPeriode: ${displayDates.senin} s/d ${displayDates.minggu}\n\nDikirim otomatis dari Sistem Management Agen`);

                const directUrl = `https://api.telegram.org/bot${cleanBotToken}/sendPhoto`;

                try {
                    let response = await fetch(directUrl, {
                        method: 'POST',
                        body: formDataToSend
                    });

                    if (!response.ok && response.status !== 401) {
                        const proxyUrl = `https://corsproxy.io/?` + encodeURIComponent(directUrl);
                        response = await fetch(proxyUrl, {
                            method: 'POST',
                            body: formDataToSend
                        });
                    }

                    const resData = await response.json();

                    if (resData.ok) {
                        showToast("Berhasil mengirim jadwal ke Telegram!", "success");
                    } else {
                        console.error("Telegram API Error:", resData);
                        showToast("Gagal kirim Telegram: " + (resData.description || "Terjadi kesalahan API"), "error");
                    }
                } catch (apiErr) {
                    console.error("Network Error Telegram API:", apiErr);
                    showToast("Gagal koneksi ke Telegram. Periksa koneksi jaringan Anda.", "error");
                } finally {
                    setIsSendingTelegram(false);
                }
            }, 'image/png');

        } catch (error) {
            console.error("Error sending image to Telegram:", error);
            showToast("Gagal mengirim ke Telegram: " + error.message, "error");
            setIsSendingTelegram(false);
        }
    };

