const formatRP = (val) => {
    const isNegative = val < 0;
    const formatted = new Intl.NumberFormat('id-ID', { 
        style: 'currency', 
        currency: 'IDR', 
        maximumFractionDigits: 0 
    }).format(Math.abs(val) || 0);
    
    if (isNegative) {
        return `-${formatted} (Selisih Harga)`;
    }
    return formatted;
};

const CountUp = ({ value }) => {
    const [displayValue, setDisplayValue] = useState(0);
    const frameRef = useRef();
    const startTimeRef = useRef();
    const duration = 1000; 

    useEffect(() => {
        const end = parseInt(value) || 0;
        const start = displayValue;
        
        if (start === end) return;

        const animate = (timestamp) => {
            if (!startTimeRef.current) startTimeRef.current = timestamp;
            const progress = timestamp - startTimeRef.current;
            const percentage = Math.min(progress / duration, 1);
            
            const easeOutQuart = 1 - Math.pow(1 - percentage, 4);
            const currentCount = Math.floor(start + (end - start) * easeOutQuart);
            
            setDisplayValue(currentCount);

            if (percentage < 1) {
                frameRef.current = requestAnimationFrame(animate);
            }
        };

        startTimeRef.current = null;
        frameRef.current = requestAnimationFrame(animate);

        return () => cancelAnimationFrame(frameRef.current);
    }, [value]);

    return <span>{formatRP(displayValue)}</span>;
};

// --- HELPER & IKON KHUSUS TAMPILAN DASHBOARD ---
const formatCompact = (val) => {
    const n = Number(val) || 0;
    const abs = Math.abs(n);
    if (abs >= 1e9) return `${(n / 1e9).toFixed(1).replace(/\.0$/, '')} M`;
    if (abs >= 1e6) return `${(n / 1e6).toFixed(1).replace(/\.0$/, '')} jt`;
    if (abs >= 1e3) return `${(n / 1e3).toFixed(0)} rb`;
    return String(n);
};

