    const parseNum = (val, isAntum = false) => {
        if (!val) return 0;
        if (typeof val === 'number') return val;
        let clean = String(val).trim();
        if (isAntum) {
            clean = clean.replace(/,/g, "").replace(/\./g, "");
        } else {
            clean = clean.replace(/\./g, "").replace(/,/g, ".");
        }
        return parseFloat(clean) || 0;
    };

    const parseFinalBalance = (text, sKey) => {
        if (!text) return null;
        const strText = String(text);

        if (sKey === 'NEWBIEZ') {
            const newbiezMatch = strText.match(/=\s*([\d\.,]+)\s*@/i);
            if (newbiezMatch) {
                let rawNum = newbiezMatch[1].trim(); 
                rawNum = rawNum.replace(/,/g, '.');
                const parts = rawNum.split('.');
                if (parts.length > 1) {
                    const lastPart = parts[parts.length - 1];
                    if (lastPart.length <= 2) {
                        parts.pop(); 
                    }
                }
                const cleanDigits = parts.join('');
                return parseInt(cleanDigits, 10) || 0;
            }
        }

        if (sKey === 'AMC') {
            const amcMatch = strText.match(/Rp\.?\s*([\d\.,]+)/i);
            if (amcMatch) return parseNum(amcMatch[1]);
        }
        if (sKey === 'OASIS') {
            const oasisMatch = strText.match(/Rp\.?\s*([\d\.]+),/i);
            if (oasisMatch) return parseNum(oasisMatch[1]);
        }
        if (sKey === 'ANTUM') {
            const antumMatch = strText.match(/=\s*([\d\.,]+)/i) || strText.match(/Sal\s*([\d\.,]+)/i);
            if (antumMatch) return parseNum(antumMatch[1], true);
        }
        
        let match = strText.match(/(?:Sal|Saldo|Sisa|Sisa Saldo)\.?\s*Rp\.?\s*([\d\.,]+)/i) || 
                    strText.match(/Rp\.?\s*([\d\.,]+)/i) || 
                    strText.match(/([\d\.,]+)\s*@/);
                    
        return match ? parseNum(match[1]) : null;
    };

    const processFile = (file) => {
        if (!file) return;
        const reader = new FileReader();
        reader.onload = async (e) => {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { type: 'array' });
            const sheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(sheet, { raw: false });

            try {
                const rawHeaderJson = XLSX.utils.sheet_to_json(sheet, { defval: "", header: "A" });
                const firstCell = String(rawHeaderJson[0]?.['A'] || '').toLowerCase();
                const speedRows = (firstCell.includes('tgl') || firstCell.includes('entri') || firstCell.includes('tanggal')) ? rawHeaderJson.slice(1) : rawHeaderJson;

                const BATCH_SIZE = 400;
                const uploadDay = getWibDayString();

                const existingSnap = await getDocs(collection(db, "speed_log_data"));
                const staleDocs = existingSnap.docs.filter(d => d.data().uploadDay !== uploadDay);
                for (let i = 0; i < staleDocs.length; i += BATCH_SIZE) {
                    const delBatch = writeBatch(db);
                    staleDocs.slice(i, i + BATCH_SIZE).forEach(d => delBatch.delete(d.ref));
                    await delBatch.commit();
                }

                for (let i = 0; i < speedRows.length; i += BATCH_SIZE) {
                    const chunk = speedRows.slice(i, i + BATCH_SIZE);
                    const batch = writeBatch(db);
                    chunk.forEach((row) => {
                        const rowRef = doc(collection(db, "speed_log_data"));
                        batch.set(rowRef, { 
                            ...row, 
                            rawDate: new Date().toISOString(),
                            uploadDay: uploadDay,
                            created_at: Timestamp.now()
                        });
                    });
                    await batch.commit();
                }
            } catch (err) {
                console.error("Gagal sinkronisasi otomatis ke Log Speed Firestore:", err);
            }

            let tempYesterday = { ...balances }; 
            let tempBalances = { ...balances };
            let tempDates = { ...balanceDates };
            let tempDaily = { ...dailyData };
            let tempUsage = { ...supplierDailyUsage };
            let tempAlertStatus = { ...alertSentStatus };
            let lastUpdateTimes = { DAS: 0, AMC: 0, HAO: 0, NEWBIEZ: 0, OASIS: 0, ANTUM: 0 };
            let newAccJual = totals.jual;
            let newAccModal = totals.modal;
            let productCounts = {};

            let countSukses = 0;
            let countGagal = 0;

            let fileStats = {
                fileName: file.name,
                uploadTime: new Date().toLocaleString('id-ID'),
                id: Date.now(),
                totalJual: 0,
                totalModal: 0,
                trxSukses: 0,
                trxGagal: 0
            };

            jsonData.forEach(row => {
                const getVal = (kws) => {
                    const key = Object.keys(row).find(k => kws.some(kw => k.trim().toLowerCase() === kw.toLowerCase()));
                    return row[key] ? String(row[key]).trim() : "";
                };
                
                const statusRaw = (getVal(['Status', 'Keterangan Status', 'sts']) || "").toLowerCase();
                const kolomSVal = (getVal(['S', 'Status Provider']) || "").toLowerCase();
                const msgVal = (getVal(['Message', 'Keterangan', 'SN', 'Ket', 'Berita', 'Jawaban Provider']) || "").toLowerCase();

                const isFail = statusRaw.includes('gagal') || statusRaw.includes('reject') || statusRaw.includes('cancel') || 
                               statusRaw.includes('fail') || statusRaw.includes('batal') || statusRaw.includes('error') ||
                               kolomSVal.includes('gagal') || kolomSVal.includes('reject') || kolomSVal.includes('cancel') || 
                               msgVal.includes('gagal') || msgVal.includes('sisa saldo tidak cukup') || msgVal.includes('saldo tidak cukup');

                const status = isFail ? 'gagal' : 'sukses';

                const kodeProduk = (getVal(['Kode Produk', 'Produk', 'Kode']) || "").toUpperCase();
                const supplierRaw = (getVal(['Nama Supplier', 'Supplier', 'Provider', 'Vendor']) || "UNKNOWN").toUpperCase();
                const message = getVal(['Message', 'Keterangan', 'SN', 'Ket', 'Berita', 'Jawaban Provider']);
                const tglRaw = getVal(['Tanggal', 'Waktu', 'Date', 'Time']);
                const currentRecordTime = new Date(tglRaw).getTime() || Date.now();
                const dateOnly = tglRaw ? tglRaw.split(' ')[0] : new Date().toISOString().split('T')[0];
                const hrgModal = parseNum(getVal(['Harga Modal', 'Modal', 'HPP', 'Harga Beli']));
                const hrgJual = parseNum(getVal(['Harga Jual', 'Harga', 'Jual']));

                let sKey = null;
                if (supplierRaw.includes('DAS')) sKey = 'DAS';
                else if (supplierRaw.includes('AMC')) sKey = 'AMC';
                else if (supplierRaw.includes('HAO')) sKey = 'HAO';
                else if (supplierRaw.includes('NEWBIEZ')) sKey = 'NEWBIEZ';
                else if (supplierRaw.includes('OASIS')) sKey = 'OASIS';
                else if (supplierRaw.includes('ANTUM')) sKey = 'ANTUM';

                if (status === 'sukses') {
                    countSukses++;
                    newAccModal += hrgModal;
                    newAccJual += hrgJual;
                    fileStats.totalJual += hrgJual;
                    fileStats.totalModal += hrgModal;
                    
                    if(kodeProduk) {
                        productCounts[kodeProduk] = (productCounts[kodeProduk] || 0) + 1;
                    }

                    if(!tempDaily[dateOnly]) tempDaily[dateOnly] = { jual: 0, modal: 0, profit: 0 };
                    tempDaily[dateOnly].jual += hrgJual;
                    tempDaily[dateOnly].modal += hrgModal;
                    tempDaily[dateOnly].profit += (hrgJual - hrgModal);
                    
                    if (sKey) {
                        if (!tempUsage[dateOnly]) tempUsage[dateOnly] = { DAS: 0, AMC: 0, HAO: 0, NEWBIEZ: 0, OASIS: 0, ANTUM: 0 };
                        tempUsage[dateOnly][sKey] = (tempUsage[dateOnly][sKey] || 0) + hrgModal;
                    }
                } else if (status === 'gagal') {
                    countGagal++;
                }
                
                if (sKey) {
                    const saldoBaru = parseFinalBalance(message, sKey);
                    if (saldoBaru !== null && currentRecordTime >= (lastUpdateTimes[sKey] || 0)) {
                        tempBalances[sKey] = saldoBaru;
                        tempDates[sKey] = tglRaw || new Date().toLocaleString('id-ID');
                        lastUpdateTimes[sKey] = currentRecordTime;
                    }
                }
            });

            if (alarmEnabled) {
                Object.entries(tempBalances).forEach(([name, bal]) => {
                    const isSupplierAlarmOn = supplierAlarmSettings[name] !== false;
                    if (isSupplierAlarmOn && bal > 0 && bal < lowBalanceThreshold) {
                        if (!tempAlertStatus[name]) {
                            sendTelegramAlert(name, bal);
                            tempAlertStatus[name] = true; 
                        }
                    } else if (bal >= lowBalanceThreshold || !isSupplierAlarmOn) {
                        tempAlertStatus[name] = false; 
                    }
                });
            }

            fileStats.trxSukses = countSukses;
            fileStats.trxGagal = countGagal;

            const sortedProducts = Object.entries(productCounts)
                .map(([kode, qty]) => ({ kode, qty }))
                .sort((a, b) => b.qty - a.qty)
                .slice(0, 5);

            await syncToCloud({
                balances: tempBalances,
                balanceDates: tempDates,
                totals: { jual: newAccJual, modal: newAccModal, profit: newAccJual - newAccModal },
                dailyData: tempDaily,
                yesterdayBalances: tempYesterday,
                supplierDailyUsage: tempUsage,
                topProducts: sortedProducts,
                uploadHistory: [fileStats, ...uploadHistory].slice(0, 10),
                alertSentStatus: tempAlertStatus
            });
            
            showToast(`File diproses! ${countSukses} Sukses & ${countGagal} Gagal. Saldo & Log Speed diperbarui.`, "success");
            setCurrentPage('dashboard');
        };
        reader.readAsArrayBuffer(file);
    };

