        suppliersList.forEach(name => {
            suppliers[name] = getSupData(name);
        });

        suppliers.isLocked = isSnapshotLocked;

        let totalKemarin = 0;
        let totalPakai = 0;
        let totalReal = 0;
        let anyJanggal = false;
        let totalTambah = 0;
        let tambahBCA = 0;
        let tambahBRI = 0;

