/* ------------------------------ Helper ------------------------------ */

const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 8);

const formatTime = (seconds) => {
    if (seconds <= 0) return "00:00";
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${String(mins).padStart(2, '0')}:${String(secs).padStart(2, '0')}`;
};

const formatBytes = (n) => {
    if (n < 1024) return `${n} B`;
    if (n < 1024 * 1024) return `${(n / 1024).toFixed(0)} KB`;
    return `${(n / (1024 * 1024)).toFixed(2)} MB`;
};

const estimateBytes = (messages, templates, logs) => {
    let n = 0;
    (messages || []).forEach(m => { n += (m.text || "").length + (m.fileData || "").length + 80; });
    (templates || []).forEach(t => { n += (t.text || "").length + (t.title || "").length + (t.fileData || "").length + 120; });
    (logs || []).forEach(l => { n += (l.fullText || "").length + (l.content || "").length + 180; });
    return n;
};

