const buildLog = (msg, ok, source, error) => {
    const d = new Date();
    const text = (msg && msg.text) || "";
    return {
        id: uid(),
        ts: d.getTime(),
        time: d.toLocaleTimeString('id-ID'),
        date: d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' }),
        content: text ? (text.length > 45 ? text.substring(0, 45) + "…" : text) : "Media saja",
        fullText: text.substring(0, MAX_LOG_TEXT),
        hasMedia: !!(msg && msg.fileData),
        source: source || "AUTO",
        status: ok ? "SUCCESS" : "FAILED",
        error: ok ? "" : (error || "Tidak diketahui")
    };
};

// Kompres gambar di browser agar dokumen Firestore tetap ringan & UI tidak lag
const compressImage = (file) => new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("Gagal membaca file"));
    reader.onload = () => {
        const img = new Image();
        img.onerror = () => reject(new Error("File bukan gambar yang valid"));
        img.onload = () => {
            const scale = Math.min(1, MAX_IMAGE_DIM / Math.max(img.width, img.height));
            const w = Math.max(1, Math.round(img.width * scale));
            const h = Math.max(1, Math.round(img.height * scale));
            const canvas = document.createElement('canvas');
            canvas.width = w;
            canvas.height = h;
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(0, 0, w, h);
            ctx.drawImage(img, 0, 0, w, h);
            resolve(canvas.toDataURL('image/jpeg', IMAGE_QUALITY));
        };
        img.src = reader.result;
    };
    reader.readAsDataURL(file);
});

const dataUrlToBlob = (dataUrl) => {
    const base64Data = dataUrl.split(',')[1];
    const byteCharacters = atob(base64Data);
    const byteNumbers = new Array(byteCharacters.length);
    for (let i = 0; i < byteCharacters.length; i++) {
        byteNumbers[i] = byteCharacters.charCodeAt(i);
    }
    return new Blob([new Uint8Array(byteNumbers)], { type: 'image/jpeg' });
};

// --- Fungsi Kirim Telegram (mengembalikan { ok, error }) ---
const sendToTelegram = async (msgObj) => {
    if (!msgObj || (!msgObj.text && !msgObj.fileData)) {
        return { ok: false, error: "Pesan kosong (tidak ada teks maupun gambar)" };
    }
    try {
        let response;
        if (msgObj.fileData) {
            const formData = new FormData();
            formData.append('chat_id', CHAT_ID);
            formData.append('photo', dataUrlToBlob(msgObj.fileData), 'image.jpg');
            formData.append('caption', msgObj.text || "");
            formData.append('parse_mode', 'HTML');
            response = await fetch(`https://api.telegram.org/bot${BOT_TOKEN}/sendPhoto`, {
                method: 'POST',
                body: formData
            });
        } else {
            response = await fetch(`https://api.telegram.org/bot${BOT_TOKEN}/sendMessage`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ chat_id: CHAT_ID, text: msgObj.text, parse_mode: "HTML" })
            });
        }
        if (response.ok) return { ok: true, error: "" };
        let desc = `HTTP ${response.status}`;
        try {
            const j = await response.json();
            if (j && j.description) desc = j.description;
        } catch (e) { /* abaikan */ }
        return { ok: false, error: desc };
    } catch (err) {
        console.error("Telegram Error:", err);
        return { ok: false, error: (err && err.message) || "Koneksi bermasalah" };
    }
};

