const SyncPill = ({ loading, saving, error, dirty, lastSavedAt }) => {
    let tone = "bg-emerald-50 text-emerald-700 border-emerald-200";
    let dot = "bg-emerald-500";
    let label = lastSavedAt ? `Tersinkron • ${lastSavedAt.toLocaleTimeString('id-ID')}` : "Tersinkron dengan Firestore";
    if (loading) {
        tone = "bg-slate-50 text-slate-500 border-slate-200"; dot = "bg-slate-400"; label = "Memuat data…";
    } else if (saving) {
        tone = "bg-blue-50 text-blue-700 border-blue-200"; dot = "bg-blue-500"; label = "Menyimpan ke Firestore…";
    } else if (error) {
        tone = "bg-red-50 text-red-700 border-red-200"; dot = "bg-red-500"; label = "Gagal sinkron — coba simpan lagi";
    } else if (dirty) {
        tone = "bg-amber-50 text-amber-700 border-amber-200"; dot = "bg-amber-500"; label = "Ada perubahan belum disimpan";
    }
    return (
        <span className={`inline-flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs font-medium ${tone}`}>
            <span className={`h-2 w-2 rounded-full ${dot} ${saving || loading ? 'animate-pulse' : ''}`} />
            {label}
        </span>
    );
};

