const HistoryTab = ({ logs, onClear }) => {
    const [statusFilter, setStatusFilter] = useState("ALL");
    const [sourceFilter, setSourceFilter] = useState("ALL");
    const [query, setQuery] = useState("");
    const [expandedId, setExpandedId] = useState(null);

    const stats = useMemo(() => {
        const success = logs.filter(l => l.status === "SUCCESS").length;
        const failed = logs.length - success;
        const rate = logs.length ? Math.round((success / logs.length) * 100) : 0;
        return { total: logs.length, success, failed, rate };
    }, [logs]);

    const filtered = useMemo(() => {
        const q = query.trim().toLowerCase();
        return logs.filter(l => {
            if (statusFilter !== "ALL" && l.status !== statusFilter) return false;
            if (sourceFilter !== "ALL" && l.source !== sourceFilter) return false;
            if (q) {
                const hay = `${l.fullText || ""} ${l.content || ""}`.toLowerCase();
                if (!hay.includes(q)) return false;
            }
            return true;
        });
    }, [logs, statusFilter, sourceFilter, query]);

    const chip = (active) => `rounded-lg border px-3 py-1.5 text-xs font-semibold transition ${active ? 'border-slate-900 bg-slate-900 text-white' : 'border-slate-200 bg-white text-slate-500 hover:bg-slate-50'}`;

    return (
        <div className="space-y-5">
            <div className="grid grid-cols-2 gap-3 md:grid-cols-4">
                {[
                    { label: "Total Pengiriman", value: stats.total, tone: "text-slate-900" },
                    { label: "Berhasil", value: stats.success, tone: "text-emerald-600" },
                    { label: "Gagal", value: stats.failed, tone: "text-red-600" },
                    { label: "Tingkat Sukses", value: `${stats.rate}%`, tone: "text-blue-600" }
                ].map(s => (
                    <div key={s.label} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm">
                        <p className="text-xs font-medium text-slate-500">{s.label}</p>
                        <p className={`mt-1 text-2xl font-semibold tabular-nums ${s.tone}`}>{s.value}</p>
                    </div>
                ))}
            </div>

            <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm md:p-5">
                <div className="mb-4 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                    <div className="relative w-full lg:max-w-xs">
                        <span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"><Icon name="search" /></span>
                        <input
                            value={query}
                            onChange={(e) => setQuery(e.target.value)}
                            placeholder="Cari isi pesan…"
                            className="w-full rounded-xl border border-slate-200 bg-slate-50 py-2.5 pl-9 pr-3 text-sm outline-none transition focus:border-blue-400 focus:bg-white"
                        />
                    </div>
                    <div className="flex flex-wrap items-center gap-2">
                        {[["ALL", "Semua"], ["SUCCESS", "Berhasil"], ["FAILED", "Gagal"]].map(([v, l]) => (
                            <button key={v} onClick={() => setStatusFilter(v)} className={chip(statusFilter === v)}>{l}</button>
                        ))}
                        <span className="mx-1 hidden h-5 w-px bg-slate-200 lg:block" />
                        {[["ALL", "Semua sumber"], ["AUTO", "Otomatis"], ["MANUAL", "Manual"], ["TEMPLATE", "Template"]].map(([v, l]) => (
                            <button key={v} onClick={() => setSourceFilter(v)} className={chip(sourceFilter === v)}>{l}</button>
                        ))}
                    </div>
                </div>

                {filtered.length === 0 ? (
                    <div className="rounded-2xl border-2 border-dashed border-slate-200 p-10 text-center">
                        <p className="text-sm font-semibold text-slate-600">{logs.length === 0 ? "Belum ada riwayat pengiriman" : "Tidak ada riwayat yang cocok"}</p>
                        <p className="mt-1 text-xs text-slate-400">{logs.length === 0 ? "Riwayat akan muncul otomatis setelah pesan dikirim." : "Coba ubah filter atau kata kunci pencarian."}</p>
                    </div>
                ) : (
                    <div className="space-y-2">
                        {filtered.map((log) => {
                            const ok = log.status === "SUCCESS";
                            const open = expandedId === log.id;
                            return (
                                <div key={log.id} className={`overflow-hidden rounded-xl border transition ${open ? 'border-slate-300 bg-slate-50/60' : 'border-slate-100 bg-white hover:border-slate-200'}`}>
                                    <button type="button" onClick={() => setExpandedId(open ? null : log.id)} className="flex w-full items-center gap-3 p-3 text-left">
                                        <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full ${ok ? 'bg-emerald-50 text-emerald-600' : 'bg-red-50 text-red-600'}`}>
                                            <Icon name={ok ? 'check' : 'x'} />
                                        </span>
                                        <span className="min-w-0 flex-1">
                                            <span className="block truncate text-sm font-medium text-slate-800">{log.content}</span>
                                            <span className="mt-0.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-[11px] text-slate-400">
                                                <span className="tabular-nums">{log.date ? `${log.date} • ${log.time}` : log.time}</span>
                                                {log.source && SOURCE_LABEL[log.source] && (
                                                    <span className="rounded bg-slate-100 px-1.5 py-0.5 font-semibold text-slate-500">{SOURCE_LABEL[log.source]}</span>
                                                )}
                                                {log.hasMedia && <span className="inline-flex items-center gap-1"><Icon name="image" className="w-3 h-3" /> Gambar</span>}
                                            </span>
                                        </span>
                                        <span className={`hidden rounded-md px-2 py-1 text-[11px] font-semibold sm:inline ${ok ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                                            {ok ? "Berhasil" : "Gagal"}
                                        </span>
                                        <span className={`text-slate-400 transition-transform ${open ? 'rotate-180' : ''}`}><Icon name="chevron" /></span>
                                    </button>
                                    {open && (
                                        <div className="space-y-3 border-t border-slate-200 px-4 py-3">
                                            <div>
                                                <p className="mb-1 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Isi pesan</p>
                                                <p className="whitespace-pre-wrap rounded-lg border border-slate-100 bg-white p-3 text-sm leading-relaxed text-slate-700">
                                                    {log.fullText || log.content}
                                                </p>
                                            </div>
                                            {!ok && log.error && (
                                                <div className="flex items-start gap-2 rounded-lg border border-red-100 bg-red-50 p-3 text-sm text-red-700">
                                                    <Icon name="alert" className="mt-0.5 w-4 h-4 shrink-0" />
                                                    <span><span className="font-semibold">Penyebab gagal:</span> {log.error}</span>
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}

                <div className="mt-4 flex flex-col gap-3 border-t border-slate-100 pt-4 sm:flex-row sm:items-center sm:justify-between">
                    <p className="text-xs text-slate-400">Menampilkan {filtered.length} dari {logs.length} riwayat • maksimal {MAX_LOGS} entri terbaru disimpan di Firestore.</p>
                    {logs.length > 0 && (
                        <button onClick={onClear} className="inline-flex items-center justify-center gap-1.5 rounded-xl border border-red-200 px-3.5 py-2 text-xs font-semibold text-red-600 transition hover:bg-red-50">
                            <Icon name="trash" className="w-3.5 h-3.5" /> Hapus Riwayat
                        </button>
                    )}
                </div>
            </div>
        </div>
    );
};

/* ============================ KOMPONEN UTAMA ============================ */

const Broadcast = () => {
    // --- State Navigasi ---
    const [activeTab, setActiveTab] = useState("broadcast");
    const [activeCategory, setActiveCategory] = useState("SEMUA");

    // --- State Broadcast & Templates ---
    const [broadcastMessages, setBroadcastMessages] = useState([]);
    const [isBcActive, setIsBcActive] = useState(false);
    const [nextSendIndex, setNextSendIndex] = useState(0);
    const [broadcastInterval, setBroadcastInterval] = useState(3600);
    const [countdown, setCountdown] = useState(0);
    const [isLoadingBc, setIsLoadingBc] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [isSending, setIsSending] = useState(false);
    const [templates, setTemplates] = useState([]);
    const [lockedTemplates, setLockedTemplates] = useState({});
    const [nextRunTimestamp, setNextRunTimestamp] = useState(null);
    const [lastSentTimestamp, setLastSentTimestamp] = useState(null);

    // --- State Sinkronisasi ---
    const [isDirty, setIsDirty] = useState(false);
    const [saveError, setSaveError] = useState(false);
    const [lastSavedAt, setLastSavedAt] = useState(null);

    // --- State Log, Preview, Toast, Konfirmasi ---
    const [broadcastLogs, setBroadcastLogs] = useState([]);
    const [previewItem, setPreviewItem] = useState(null);
    const [toast, setToast] = useState(null);
    const [confirmState, setConfirmState] = useState(null);

    const toastTimer = useRef(null);
    const sendingRef = useRef(false);
    const savingRef = useRef(false);
    const lastFiredRef = useRef("");
    const editVersionRef = useRef(0);

    const triggerToast = useCallback((msg, type = 'success') => {
        setToast({ msg, type });
        clearTimeout(toastTimer.current);
        toastTimer.current = setTimeout(() => setToast(null), type === 'error' ? 3500 : 2200);
    }, []);

    useEffect(() => () => clearTimeout(toastTimer.current), []);

    const markDirty = useCallback(() => {
        editVersionRef.current += 1;
        setIsDirty(true);
    }, []);

    const askConfirm = useCallback((cfg) => setConfirmState(cfg), []);

    // --- Efek Sinkronisasi Awal ---
    useEffect(() => {
        let alive = true;
        (async () => {
            try {
                const config = await getBroadcastConfig();
                if (!alive) return;
                if (config) {
                    setBroadcastMessages(normalizeMessages(config.messages));
                    setIsBcActive(config.isActive || false);
                    setNextSendIndex(config.nextIndex || 0);
                    setLastSentTimestamp(config.lastSent || null);
                    setBroadcastInterval(config.interval || 3600);
                    setTemplates(normalizeTemplates(config.templates));
                    setNextRunTimestamp(config.nextRunTimestamp || null);
                    setBroadcastLogs(normalizeLogs(config.logs));
                    setLockedTemplates(config.lockedTemplates || {});
                }
            } catch (err) {
                console.error("Gagal memuat konfigurasi broadcast:", err);
                if (alive) triggerToast("Gagal memuat data dari Firestore", 'error');
            } finally {
                if (alive) setIsLoadingBc(false);
            }
        })();
        return () => { alive = false; };
    }, [triggerToast]);

    // --- Ref state terbaru (mencegah stale closure saat menyimpan ke Firebase) ---
    const latestRef = useRef({});
    latestRef.current = {
        messages: broadcastMessages,
        isActive: isBcActive,
        nextIndex: nextSendIndex,
        lastSent: lastSentTimestamp,
        interval: broadcastInterval,
        templates: templates,
        nextRunTimestamp: nextRunTimestamp,
        logs: broadcastLogs,
        lockedTemplates: lockedTemplates
    };

    const syncToCloud = useCallback(async (updates = {}) => {
        const versionAtStart = editVersionRef.current;
        // Selalu pakai state paling baru (bukan closure lama dari interval/effect)
        const cur = latestRef.current;
        const pick = (k) => (updates[k] !== undefined ? updates[k] : cur[k]);
        const payload = {
            messages: pick('messages'),
            isActive: pick('isActive'),
            nextIndex: pick('nextIndex'),
            lastSent: pick('lastSent'),
            interval: pick('interval'),
            templates: pick('templates'),
            nextRunTimestamp: pick('nextRunTimestamp'),
            logs: pick('logs'),
            lockedTemplates: pick('lockedTemplates')
        };

        // --- PROTEKSI TEMPLATE TERKUNCI ---
        // Template yang sudah terkunci di Firebase tidak boleh hilang/tertimpa oleh proses otomatis.
        // Hanya pengguna yang membuka kunci secara manual (flag = false) yang bisa melepasnya.
        try {
            const cloud = await getBroadcastConfig();
            if (cloud) {
                const cloudLocks = cloud.lockedTemplates || {};
                const cloudTpls = Array.isArray(cloud.templates) ? cloud.templates : [];
                const mergedLocks = { ...(payload.lockedTemplates || {}) };
                const mergedTpls = Array.isArray(payload.templates) ? [...payload.templates] : [];
                let restored = false;

                Object.keys(cloudLocks).forEach((id) => {
                    if (cloudLocks[id] !== true) return;
                    if (mergedLocks[id] === false) return; // dibuka kuncinya secara manual oleh pengguna
                    if (mergedLocks[id] !== true) {
                        mergedLocks[id] = true;
                        restored = true;
                    }
                });

                Object.keys(mergedLocks).forEach((id) => {
                    if (mergedLocks[id] !== true) return;
                    const exists = mergedTpls.some(t => String(t.id) === String(id));
                    if (!exists) {
                        const fromCloud = cloudTpls.find(t => String(t.id) === String(id));
                        if (fromCloud) {
                            mergedTpls.push(fromCloud);
                            restored = true;
                        }
                    }
                });

                if (restored) {
                    payload.lockedTemplates = mergedLocks;
                    payload.templates = mergedTpls;
                    setLockedTemplates(mergedLocks);
                    setTemplates(normalizeTemplates(mergedTpls));
                }
            }
        } catch (err) {
            console.error("Proteksi Template Terkunci Error:", err);
        }

        try {
            await updateBroadcastConfig(payload);
            if (updates.nextRunTimestamp !== undefined) setNextRunTimestamp(updates.nextRunTimestamp);
            setLastSavedAt(new Date());
            setSaveError(false);
            // Hanya dianggap "tersimpan" bila tidak ada edit baru selama proses simpan
            if (editVersionRef.current === versionAtStart) setIsDirty(false);
            return true;
        } catch (err) {
            console.error("Gagal sinkron ke Firestore:", err);
            setSaveError(true);
            return false;
        }
    }, []);

    // Simpan semua perubahan (broadcast + template + riwayat) ke Firestore
    const handleSaveAll = useCallback(async () => {
        if (savingRef.current) return;
        savingRef.current = true;
        setIsSaving(true);
        const ok = await syncToCloud({});
        savingRef.current = false;
        setIsSaving(false);
        triggerToast(ok ? "Tersimpan ke Firestore" : "Gagal menyimpan ke Firestore, coba lagi", ok ? 'success' : 'error');
    }, [syncToCloud, triggerToast]);

    // Ctrl/Cmd + S
    useEffect(() => {
        const onKey = (e) => {
            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
                e.preventDefault();
                handleSaveAll();
            }
        };
        window.addEventListener('keydown', onKey);
        return () => window.removeEventListener('keydown', onKey);
    }, [handleSaveAll]);

    // Peringatan bila menutup tab saat masih ada perubahan belum disimpan
    useEffect(() => {
        if (!isDirty) return undefined;
        const onBeforeUnload = (e) => { e.preventDefault(); e.returnValue = ""; };
        window.addEventListener('beforeunload', onBeforeUnload);
        return () => window.removeEventListener('beforeunload', onBeforeUnload);
    }, [isDirty]);

    // --- Riwayat ---
    const appendLog = useCallback((msg, ok, source, error) => {
        const entry = buildLog(msg, ok, source, error);
        const updated = [entry, ...(latestRef.current.logs || [])].slice(0, MAX_LOGS);
        latestRef.current.logs = updated; // langsung tersedia untuk syncToCloud berikutnya
        setBroadcastLogs(updated);
        return updated;
    }, []);

    // --- Countdown awal / saat timestamp berubah ---
    useEffect(() => {
        if (nextRunTimestamp) {
            const diff = Math.round((nextRunTimestamp - Date.now()) / 1000);
            setCountdown(diff > 0 ? diff : 0);
        } else {
            setCountdown(0);
        }
    }, [nextRunTimestamp]);

    // --- Logika Loop Broadcast ---
    // Loop hanya dibuat ulang saat engine dinyalakan/dimatikan; state terbaru dibaca dari latestRef.
    useEffect(() => {
        if (!isBcActive) return undefined;

        const tick = async () => {
            const cur = latestRef.current;
            const msgs = cur.messages || [];
            if (msgs.length === 0 || sendingRef.current) return;

            const now = new Date();
            const nowMs = now.getTime();
            const safeIdx = cur.nextIndex >= msgs.length ? 0 : cur.nextIndex;
            const currentMsg = msgs[safeIdx];
            if (!currentMsg) return;

            const wibTime = currentMsg.scheduledWib;
            let shouldSend = false;

            if (wibTime) {
                const [h, m] = wibTime.split(':');
                const fireKey = `${currentMsg.id}|${now.toDateString()}|${wibTime}`;
                if (
                    now.getHours() === parseInt(h, 10) &&
                    now.getMinutes() === parseInt(m, 10) &&
                    lastFiredRef.current !== fireKey
                ) {
                    shouldSend = true;
                    lastFiredRef.current = fireKey; // cegah kirim ganda dalam menit yang sama
                }
            } else if (cur.nextRunTimestamp) {
                const diff = Math.round((cur.nextRunTimestamp - nowMs) / 1000);
                setCountdown(diff > 0 ? diff : 0);
                if (diff <= 0) shouldSend = true;
            }

            if (!shouldSend) return;

            sendingRef.current = true;
            setIsSending(true);
            try {
                const result = await sendToTelegram(currentMsg);
                const updatedLogs = appendLog(currentMsg, result.ok, "AUTO", result.error);

                // Pakai daftar pesan terbaru (pengguna bisa saja mengedit selama proses kirim)
                const updatedMessages = [...latestRef.current.messages];
                if (result.ok) {
                    const pos = updatedMessages.findIndex(m => m.id === currentMsg.id);
                    if (pos !== -1) updatedMessages.splice(pos, 1);
                }

                const nextIdx = updatedMessages.length > 0 ? (safeIdx % updatedMessages.length) : 0;
                const nowStr = new Date().toLocaleTimeString('id-ID');
                const nextRun = Date.now() + (latestRef.current.interval * 1000);

                setBroadcastMessages(updatedMessages);
                setNextSendIndex(nextIdx);
                setLastSentTimestamp(nowStr);

                await syncToCloud({
                    messages: updatedMessages,
                    nextIndex: nextIdx,
                    lastSent: nowStr,
                    nextRunTimestamp: updatedMessages.length > 0 ? nextRun : null,
                    logs: updatedLogs
                });
            } finally {
                sendingRef.current = false;
                setIsSending(false);
            }
        };

        const timer = setInterval(tick, 1000);
        return () => clearInterval(timer);
    }, [isBcActive, appendLog, syncToCloud]);

    // --- Handler Broadcast ---
    const handleMessageChange = useCallback((id, field, value) => {
        setBroadcastMessages(prev => prev.map(m => (m.id === id ? { ...m, [field]: value } : m)));
        markDirty();
    }, [markDirty]);

    const handleMessageImage = useCallback(async (id, file) => {
        if (file.size > MAX_UPLOAD_MB * 1024 * 1024) {
            triggerToast(`Ukuran gambar maksimal ${MAX_UPLOAD_MB} MB`, 'error');
            return;
        }
        try {
            const dataUrl = await compressImage(file);
            handleMessageChange(id, 'fileData', dataUrl);
        } catch (err) {
            triggerToast(err.message || "Gagal memproses gambar", 'error');
        }
    }, [handleMessageChange, triggerToast]);

    const handleAddSlot = useCallback(() => {
        setBroadcastMessages(prev => [...prev, { id: uid(), text: "", fileData: null, scheduledWib: "" }]);
        markDirty();
        triggerToast("Slot antrian ditambahkan");
    }, [markDirty, triggerToast]);

    const handleDeleteMessage = useCallback((id) => {
        const updated = latestRef.current.messages.filter(m => m.id !== id);
        setBroadcastMessages(updated);
        syncToCloud({ messages: updated });
        triggerToast("Slot dihapus");
    }, [syncToCloud, triggerToast]);

    const handleInstantSend = useCallback(async (id) => {
        const msg = latestRef.current.messages.find(m => m.id === id);
        if (!msg) return;
        if (sendingRef.current) {
            triggerToast("Sedang ada proses kirim, coba sesaat lagi", 'error');
            return;
        }
        sendingRef.current = true;
        setIsSending(true);
        try {
            const result = await sendToTelegram(msg);
            appendLog(msg, result.ok, "MANUAL", result.error);
            if (result.ok) {
                const updated = latestRef.current.messages.filter(m => m.id !== id);
                setBroadcastMessages(updated);
                triggerToast("Terkirim & slot dihapus");
                await syncToCloud({ messages: updated });
            } else {
                triggerToast(`Gagal mengirim: ${result.error}`, 'error');
                await syncToCloud({});
            }
        } finally {
            sendingRef.current = false;
            setIsSending(false);
        }
    }, [appendLog, syncToCloud, triggerToast]);

    const handleStartBroadcast = useCallback((active) => {
        const nextRun = active ? Date.now() + (latestRef.current.interval * 1000) : null;
        setIsBcActive(active);
        setNextRunTimestamp(nextRun);
        syncToCloud({ isActive: active, nextRunTimestamp: nextRun });
    }, [syncToCloud]);

    const handleSelectInterval = useCallback((value) => {
        const nextRun = latestRef.current.isActive ? Date.now() + (value * 1000) : null;
        setBroadcastInterval(value);
        setNextRunTimestamp(nextRun);
        syncToCloud({ interval: value, nextRunTimestamp: nextRun });
    }, [syncToCloud]);

    const resetBroadcastQueue = useCallback(() => {
        const interval = latestRef.current.interval;
        const nextRun = Date.now() + (interval * 1000);
        setNextSendIndex(0);
        setCountdown(interval);
        if (latestRef.current.isActive) setNextRunTimestamp(nextRun);
        syncToCloud({ nextIndex: 0, nextRunTimestamp: latestRef.current.isActive ? nextRun : null });
        triggerToast("Antrian di-reset");
    }, [syncToCloud, triggerToast]);

    const handleDeleteAllMessages = useCallback(() => {
        askConfirm({
            title: "Hapus semua slot antrian?",
            message: "Seluruh pesan di antrian broadcast akan dihapus permanen dari Firestore.",
            confirmLabel: "Hapus semua",
            onConfirm: () => {
                setBroadcastMessages([]);
                setNextSendIndex(0);
                syncToCloud({ messages: [], nextIndex: 0 });
                triggerToast("Semua slot dihapus");
            }
        });
    }, [askConfirm, syncToCloud, triggerToast]);

    const handleClearLogs = useCallback(() => {
        askConfirm({
            title: "Hapus seluruh riwayat?",
            message: "Riwayat pengiriman akan dihapus permanen dari Firestore dan tidak bisa dikembalikan.",
            confirmLabel: "Hapus riwayat",
            onConfirm: () => {
                latestRef.current.logs = [];
                setBroadcastLogs([]);
                syncToCloud({ logs: [] });
                triggerToast("Riwayat dihapus");
            }
        });
    }, [askConfirm, syncToCloud, triggerToast]);

    // --- Handler Template ---
    const handleTemplateChange = useCallback((id, field, value) => {
        if (latestRef.current.lockedTemplates[id]) return;
        setTemplates(prev => prev.map(t => (t.id === id ? { ...t, [field]: value } : t)));
        markDirty();
    }, [markDirty]);

    const handleTemplateImage = useCallback(async (id, file) => {
        if (file.size > MAX_UPLOAD_MB * 1024 * 1024) {
            triggerToast(`Ukuran gambar maksimal ${MAX_UPLOAD_MB} MB`, 'error');
            return;
        }
        try {
            const dataUrl = await compressImage(file);
            handleTemplateChange(id, 'fileData', dataUrl);
        } catch (err) {
            triggerToast(err.message || "Gagal memproses gambar", 'error');
        }
    }, [handleTemplateChange, triggerToast]);

    const handleCreateTemplate = useCallback(() => {
        setTemplates(prev => [{ id: Date.now(), category: "TEMPLATE HARIAN", title: "", text: "", fileData: null }, ...prev]);
        markDirty();
    }, [markDirty]);

    const toggleLock = useCallback((id) => {
        const cur = latestRef.current;
        const newLocks = { ...cur.lockedTemplates, [id]: !cur.lockedTemplates[id] };
        setLockedTemplates(newLocks);
        // Saat dikunci, isi template ikut disimpan permanen ke Firebase bersama flag kuncinya
        syncToCloud({ lockedTemplates: newLocks, templates: cur.templates });
        triggerToast(newLocks[id] ? "Template dikunci & tersimpan" : "Kunci template dibuka");
    }, [syncToCloud, triggerToast]);

    const handleDeleteTemplate = useCallback((id) => {
        askConfirm({
            title: "Hapus template ini?",
            message: "Template akan dihapus dari library. Klik Simpan agar perubahan tersinkron ke Firestore.",
            confirmLabel: "Hapus",
            onConfirm: () => {
                setTemplates(prev => prev.filter(t => t.id !== id));
                markDirty();
            }
        });
    }, [askConfirm, markDirty]);

    const handleSendTemplate = useCallback(async (tpl) => {
        if (sendingRef.current) {
            triggerToast("Sedang ada proses kirim, coba sesaat lagi", 'error');
            return;
        }
        sendingRef.current = true;
        setIsSending(true);
        try {
            const result = await sendToTelegram(tpl);
            appendLog({ text: tpl.text || tpl.title || "", fileData: tpl.fileData }, result.ok, "TEMPLATE", result.error);
            triggerToast(result.ok ? "Template terkirim" : `Gagal mengirim: ${result.error}`, result.ok ? 'success' : 'error');
            await syncToCloud({});
        } finally {
            sendingRef.current = false;
            setIsSending(false);
        }
    }, [appendLog, syncToCloud, triggerToast]);

    // --- Data turunan ---
    const filteredTemplates = useMemo(
        () => templates.filter(t => activeCategory === "SEMUA" || t.category === activeCategory),
        [templates, activeCategory]
    );

    const docBytes = useMemo(
        () => estimateBytes(broadcastMessages, templates, broadcastLogs),
        [broadcastMessages, templates, broadcastLogs]
    );
    const docPercent = Math.min(100, Math.round((docBytes / DOC_SOFT_LIMIT) * 100));

    const safeNextIdx = nextSendIndex >= broadcastMessages.length ? 0 : nextSendIndex;
    const nextMsg = broadcastMessages[safeNextIdx];
    const statusText = isLoadingBc
        ? "Memuat…"
        : isBcActive
            ? (broadcastMessages.length === 0 ? "Aktif • antrian kosong" : `Berikutnya ${(nextMsg && nextMsg.scheduledWib) || formatTime(countdown)}`)
            : "Offline";

    const tabs = [
        { id: "broadcast", label: "Broadcast", icon: "megaphone", count: broadcastMessages.length },
        { id: "template", label: "Templates", icon: "file", count: templates.length },
        { id: "history", label: "Riwayat", icon: "history", count: broadcastLogs.length }
    ];

    const btnBase = "inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold shadow-sm transition active:scale-95 disabled:cursor-not-allowed disabled:opacity-60";

    return (
        <div className="relative mx-auto max-w-7xl space-y-6 rounded-3xl bg-slate-50 p-4 pb-28 md:p-8 md:pb-28">

            <Toast toast={toast} />
            <PreviewModal item={previewItem} onClose={() => setPreviewItem(null)} />
            <ConfirmDialog
                state={confirmState}
                onCancel={() => setConfirmState(null)}
                onConfirm={() => {
                    const fn = confirmState && confirmState.onConfirm;
                    setConfirmState(null);
                    if (fn) fn();
                }}
            />

            {/* Header Utama */}
            <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
                <div className="flex items-center gap-4">
                    <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-gradient-to-br from-blue-600 to-indigo-600 text-white shadow-lg shadow-blue-200">
                        <Icon name="megaphone" className="w-6 h-6" />
                    </div>
                    <div>
                        <h2 className="text-xl font-bold tracking-tight text-slate-900 md:text-2xl">Web Admin IFYOne</h2>
                        <p className="mt-0.5 flex items-center gap-2 text-xs font-medium text-slate-500">
                            <span className="h-2 w-2 animate-pulse rounded-full bg-emerald-500" />
                            Sistem Broadcast &amp; Template
                        </p>
                    </div>
                </div>

                <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
                    <SyncPill loading={isLoadingBc} saving={isSaving} error={saveError} dirty={isDirty} lastSavedAt={lastSavedAt} />
                    <div className="flex gap-1 overflow-x-auto rounded-xl border border-slate-200 bg-white p-1 shadow-sm no-scrollbar">
                        {tabs.map((tab) => (
                            <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`flex flex-1 items-center justify-center gap-2 whitespace-nowrap rounded-lg px-4 py-2 text-sm font-semibold transition ${activeTab === tab.id ? 'bg-blue-600 text-white shadow' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'}`}
                            >
                                <Icon name={tab.icon} />
                                {tab.label}
                                <span className={`rounded-md px-1.5 py-0.5 text-[11px] tabular-nums ${activeTab === tab.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'}`}>{tab.count}</span>
                            </button>
                        ))}
                    </div>
                </div>
            </div>

            {/* TAB: BROADCAST */}
            {activeTab === "broadcast" && (
                <div className="space-y-6">
                    <div className="grid grid-cols-1 gap-4 md:grid-cols-3 md:gap-6">

                        {/* Status Card */}
                        <div className="flex flex-col justify-between rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
                            <div className="flex items-center gap-4">
                                <div className={`flex h-12 w-12 shrink-0 items-center justify-center rounded-xl ${isBcActive ? 'bg-emerald-50 text-emerald-600 ring-4 ring-emerald-50' : 'bg-slate-100 text-slate-400'}`}>
                                    {isSending ? <Spinner className="w-5 h-5" /> : <Icon name="send" className="w-5 h-5" />}
                                </div>
                                <div className="min-w-0">
                                    <p className="text-xs font-medium text-slate-500">Status Broadcast</p>
                                    <p className={`truncate text-lg font-semibold tabular-nums ${isBcActive ? 'text-slate-900' : 'text-slate-400'}`}>
                                        {isSending ? "Mengirim…" : statusText}
                                    </p>
                                </div>
                            </div>
                            <div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-4">
                                <span className="text-sm font-medium text-slate-600">Aktifkan Engine</span>
                                <button
                                    type="button"
                                    role="switch"
                                    aria-checked={isBcActive}
                                    disabled={isLoadingBc}
                                    onClick={() => handleStartBroadcast(!isBcActive)}
                                    className={`relative inline-flex h-7 w-12 items-center rounded-full transition disabled:opacity-50 ${isBcActive ? 'bg-blue-600' : 'bg-slate-300'}`}
                                >
                                    <span className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition ${isBcActive ? 'translate-x-6' : 'translate-x-1'}`} />
                                </button>
                            </div>
                            {lastSentTimestamp && (
                                <p className="mt-3 text-xs text-slate-400">Terakhir kirim: <span className="font-semibold text-slate-600">{lastSentTimestamp}</span></p>
                            )}
                        </div>

                        {/* Interval Settings Card */}
                        <div className="flex flex-col justify-between rounded-2xl border border-slate-200 bg-white p-5 shadow-sm md:col-span-2">
                            <div>
                                <p className="mb-3 text-xs font-medium text-slate-500">Interval pengiriman antar pesan</p>
                                <div className="grid grid-cols-3 gap-2 sm:grid-cols-6">
                                    {INTERVAL_OPTIONS.map((opt) => (
                                        <button
                                            key={opt.value}
                                            onClick={() => handleSelectInterval(opt.value)}
                                            className={`rounded-xl border py-2.5 text-xs font-semibold transition ${broadcastInterval === opt.value ? 'border-blue-600 bg-blue-600 text-white shadow' : 'border-slate-200 bg-white text-slate-500 hover:border-slate-300 hover:bg-slate-50'}`}
                                        >
                                            {opt.label}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <div className="mt-4 flex flex-col gap-2 border-t border-slate-100 pt-4 text-xs text-slate-500 sm:flex-row sm:items-center sm:justify-between">
                                <span>Slot dengan jam jadwal (WIB) dikirim sesuai jamnya, mengabaikan interval.</span>
                                <span className="inline-flex items-center gap-1.5 font-semibold text-emerald-600">
                                    <Icon name="check" className="w-3.5 h-3.5" /> Hapus otomatis setelah terkirim
                                </span>
                            </div>
                        </div>
                    </div>

                    {/* Toolbar */}
                    <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                        <div>
                            <h3 className="text-base font-semibold text-slate-900">Antrian Pesan</h3>
                            <p className="text-xs text-slate-500">{broadcastMessages.length} slot • Ctrl+S untuk menyimpan cepat</p>
                        </div>
                        <div className="grid grid-cols-2 gap-2 sm:flex sm:flex-wrap">
                            <button onClick={handleAddSlot} className={`${btnBase} bg-slate-900 text-white hover:bg-slate-800`}>
                                <Icon name="plus" /> Tambah Slot
                            </button>
                            <button onClick={handleSaveAll} disabled={isSaving} className={`${btnBase} ${isSaving ? 'bg-blue-500' : 'bg-blue-600 hover:bg-blue-700'} text-white`}>
                                {isSaving ? <Spinner /> : <Icon name="save" />} {isSaving ? "Menyimpan…" : "Simpan Broadcast"}
                            </button>
                            <button onClick={resetBroadcastQueue} className={`${btnBase} border border-amber-200 bg-amber-50 text-amber-700 hover:bg-amber-100`}>
                                <Icon name="refresh" /> Reset Antrian
                            </button>
                            <button onClick={handleDeleteAllMessages} className={`${btnBase} border border-red-200 bg-red-50 text-red-600 hover:bg-red-100`}>
                                <Icon name="trash" /> Hapus Semua
                            </button>
                        </div>
                    </div>

                    {/* List Cards Antrian Broadcast */}
                    <div className="grid grid-cols-1 gap-4 md:grid-cols-2 md:gap-6 lg:grid-cols-3">
                        {broadcastMessages.map((msg, index) => (
                            <BroadcastCard
                                key={msg.id}
                                msg={msg}
                                index={index}
                                isNext={isBcActive && safeNextIdx === index}
                                onChange={handleMessageChange}
                                onImage={handleMessageImage}
                                onPreview={setPreviewItem}
                                onSend={handleInstantSend}
                                onDelete={handleDeleteMessage}
                            />
                        ))}
                    </div>

                    {!isLoadingBc && broadcastMessages.length === 0 && (
                        <div className="rounded-2xl border-2 border-dashed border-slate-200 bg-white/70 p-10 text-center">
                            <p className="text-sm font-semibold text-slate-600">Antrian broadcast kosong</p>
                            <p className="mt-1 text-xs text-slate-400">Klik “Tambah Slot” untuk membuat pesan baru.</p>
                        </div>
                    )}

                    {/* Aktivitas Terakhir */}
                    {broadcastLogs.length > 0 && (
                        <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
                            <div className="mb-3 flex items-center justify-between">
                                <p className="text-sm font-semibold text-slate-900">Aktivitas Terakhir</p>
                                <button onClick={() => setActiveTab("history")} className="text-xs font-semibold text-blue-600 hover:underline">Lihat semua riwayat →</button>
                            </div>
                            <div className="space-y-2">
                                {broadcastLogs.slice(0, 5).map((log) => (
                                    <div key={log.id} className="flex items-center justify-between gap-3 rounded-xl border border-slate-100 bg-slate-50/60 p-3">
                                        <div className="flex min-w-0 items-center gap-3">
                                            <span className="shrink-0 font-mono text-xs font-semibold text-slate-500">{log.time}</span>
                                            <span className="truncate text-sm text-slate-600">{log.content}</span>
                                        </div>
                                        <span className={`shrink-0 rounded-md px-2 py-1 text-[11px] font-semibold ${log.status === 'SUCCESS' ? 'bg-emerald-100 text-emerald-700' : 'bg-red-100 text-red-700'}`}>
                                            {log.status === 'SUCCESS' ? "Berhasil" : "Gagal"}
                                        </span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            )}

            {/* TAB: TEMPLATES */}
            {activeTab === "template" && (
                <div className="space-y-6">
                    {/* Category Selector Tabs */}
                    <div className="flex gap-2 overflow-x-auto pb-1 no-scrollbar">
                        {CATEGORIES.map((cat) => (
                            <button
                                key={cat}
                                onClick={() => setActiveCategory(cat)}
                                className={`whitespace-nowrap rounded-xl border px-4 py-2 text-xs font-semibold transition ${activeCategory === cat ? 'border-indigo-600 bg-indigo-600 text-white shadow' : 'border-slate-200 bg-white text-slate-500 hover:bg-slate-50'}`}
                            >
                                {cat}
                            </button>
                        ))}
                    </div>

                    <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm md:p-8">
                        <div className="mb-6 flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                            <div>
                                <h3 className="text-lg font-semibold text-slate-900">Library Template</h3>
                                <p className="text-xs text-slate-500">Siap kirim ke Telegram • {filteredTemplates.length} template ditampilkan</p>
                            </div>
                            <div className="flex w-full gap-2 md:w-auto">
                                <button onClick={handleSaveAll} disabled={isSaving} className={`${btnBase} flex-1 bg-emerald-600 text-white hover:bg-emerald-700 md:flex-none`}>
                                    {isSaving ? <Spinner /> : <Icon name="save" />} {isSaving ? "Menyimpan…" : "Simpan Library"}
                                </button>
                                <button onClick={handleCreateTemplate} className={`${btnBase} flex-1 bg-slate-900 text-white hover:bg-slate-800 md:flex-none`}>
                                    <Icon name="plus" /> Buat Template
                                </button>
                            </div>
                        </div>

                        {/* Grid Card Template */}
                        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 md:gap-6 lg:grid-cols-3">
                            {filteredTemplates.map(tpl => (
                                <TemplateCard
                                    key={tpl.id}
                                    tpl={tpl}
                                    locked={!!lockedTemplates[tpl.id]}
                                    onChange={handleTemplateChange}
                                    onImage={handleTemplateImage}
                                    onToggleLock={toggleLock}
                                    onDelete={handleDeleteTemplate}
                                    onPreview={setPreviewItem}
                                    onSend={handleSendTemplate}
                                />
                            ))}
                        </div>

                        {filteredTemplates.length === 0 && (
                            <div className="rounded-2xl border-2 border-dashed border-slate-200 p-10 text-center">
                                <p className="text-sm font-semibold text-slate-600">Belum ada template</p>
                                <p className="mt-1 text-xs text-slate-400">Klik “Buat Template” untuk menambahkan template baru.</p>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* TAB: RIWAYAT */}
            {activeTab === "history" && (
                <HistoryTab logs={broadcastLogs} onClear={handleClearLogs} />
            )}

            {/* Indikator ukuran data Firestore */}
            <div className="flex flex-col gap-2 rounded-2xl border border-slate-200 bg-white px-5 py-4 shadow-sm sm:flex-row sm:items-center sm:justify-between">
                <div className="min-w-0 flex-1">
                    <div className="mb-1.5 flex items-center justify-between text-xs">
                        <span className="font-medium text-slate-500">Ukuran data tersimpan (perkiraan)</span>
                        <span className={`font-semibold tabular-nums ${docPercent >= 90 ? 'text-red-600' : docPercent >= 70 ? 'text-amber-600' : 'text-slate-600'}`}>
                            {formatBytes(docBytes)} / ~1 MB
                        </span>
                    </div>
                    <div className="h-1.5 w-full overflow-hidden rounded-full bg-slate-100">
                        <div className={`h-full rounded-full transition-all ${docPercent >= 90 ? 'bg-red-500' : docPercent >= 70 ? 'bg-amber-500' : 'bg-blue-500'}`} style={{ width: `${docPercent}%` }} />
                    </div>
                </div>
                {docPercent >= 80 && (
                    <p className="text-xs font-medium text-amber-700 sm:max-w-xs sm:text-right">Mendekati batas dokumen Firestore. Hapus gambar/slot lama agar penyimpanan tidak gagal.</p>
                )}
            </div>

            {/* Bilah simpan melayang saat ada perubahan */}
            {isDirty && !isLoadingBc && (
                <div className="fixed bottom-4 left-1/2 z-[1500] w-[92%] max-w-lg -translate-x-1/2">
                    <div className="flex items-center justify-between gap-3 rounded-2xl border border-slate-700 bg-slate-900/95 px-4 py-3 text-white shadow-2xl backdrop-blur">
                        <div className="flex items-center gap-2.5 text-sm">
                            <span className="h-2 w-2 animate-pulse rounded-full bg-amber-400" />
                            <span className="font-medium">{saveError ? "Gagal sinkron, coba lagi" : "Perubahan belum disimpan"}</span>
                        </div>
                        <button onClick={handleSaveAll} disabled={isSaving} className="inline-flex items-center gap-2 rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold transition hover:bg-blue-500 active:scale-95 disabled:opacity-60">
                            {isSaving ? <Spinner /> : <Icon name="save" />} {isSaving ? "Menyimpan…" : "Simpan sekarang"}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Broadcast;