// ----------------------------------------------------------
// KODE BUYER DIGIFLAZZ (FREFIRE...) -> KODE GAMES PANEL (FFP...)
// Excel buyer memakai kode FREFIRE<angka>, tetapi angkanya TIDAK selalu
// sama dengan jumlah diamond (FREFIRE0 = 90 DM, FREFIRE40 = 140 DM,
// FREFIRE60 = 160 DM, FREFIRE2770 = 2720 DM).
// Karena itu jumlah diamond dibaca dari kolom "Produk" (nama produk),
// lalu dijadikan kode FFP<diamond>. Kode FFP inilah yang dipakai untuk
// HPP Games Panel dan untuk teks broadcast Telegram.
// ----------------------------------------------------------
const BUYER_FF_PATTERN = /^FRE{1,2}FIRE/; // FREFIRE & FREEFIRE
const NAME_HEADERS = ['produk', 'nama produk', 'product name', 'nama'];
const STATUS_HEADERS = ['status'];

// "Free Fire 1.050 Diamond" -> 1050
const diamondFromName = (name) => {
  const m = String(name || '').match(/(\d[\d.,]*)\s*(?:diamonds?|dm|dia)\b/i);
  if (!m) return null;
  const n = Number(m[1].replace(/[.,]/g, ''));
  return isFinite(n) && n > 0 ? n : null;
};

// Hasil: { code, sourceCode, note }
//  - kode bukan FREFIRE  -> dikembalikan apa adanya (sourceCode = null)
//  - kode FREFIRE        -> diubah menjadi FFP<diamond>
const toGamesPanelCode = (rawCode, name) => {
  const code = normCode(rawCode);
  if (!BUYER_FF_PATTERN.test(code)) {
    return { code, sourceCode: null, note: '' };
  }

  const fromName = diamondFromName(name);
  const tail = code.match(/(\d+)$/);
  const fromCode = tail ? Number(tail[1]) : null;
  const diamond = fromName || fromCode;

  if (!diamond) {
    // tidak bisa diterjemahkan -> biarkan, nanti ditandai "tidak ditemukan"
    return { code, sourceCode: code, note: '' };
  }

  return {
    code: `FFP${diamond}`,
    sourceCode: code,
    note: fromName
      ? ''
      : 'Diamond diambil dari angka pada kode (nama produk tidak terbaca)',
  };
};

const ERROR_LABELS = {
  kode_kosong: 'baris tanpa kode produk',
  duplikat: 'kode produk duplikat',
  game_salah: 'kode produk bukan milik game yang dipilih',
  tidak_ditemukan: 'produk tidak ditemukan',
  nonaktif: 'produk tidak aktif',
  harga_kosong: 'harga kosong',
  harga_invalid: 'harga bukan angka / tidak valid',
};

const formatRupiah = (n) => {
  if (n === null || n === undefined || isNaN(n)) return '-';
  return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
};

const normCode = (v) =>
  String(v === null || v === undefined ? '' : v)
    .trim()
    .toUpperCase()
    .replace(/\s+/g, '');

const isBlank = (v) =>
  v === null || v === undefined || String(v).trim() === '';

const delay = (ms) => new Promise((r) => setTimeout(r, ms));

// Baca harga dari sel Excel (angka, "1.600", "1,600", "Rp 1.600", "1795,5", dll)
const parsePrice = (raw) => {
  if (isBlank(raw)) return { error: 'harga_kosong', message: 'Harga kosong' };

  if (typeof raw === 'number') {
    if (!isFinite(raw))
      return { error: 'harga_invalid', message: 'Harga bukan angka' };
    if (raw <= 0)
      return { error: 'harga_invalid', message: 'Harga harus lebih dari 0' };
    return { value: raw };
  }

  let s = String(raw)
    .trim()
    .replace(/^rp\.?\s*/i, '')
    .replace(/\s/g, '');

  if (!/^[0-9.,]+$/.test(s))
    return { error: 'harga_invalid', message: 'Harga bukan angka' };

  if (/^\d{1,3}(\.\d{3})+(,\d+)?$/.test(s)) {
    // format Indonesia: 1.600 atau 1.600,50
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (/^\d{1,3}(,\d{3})+(\.\d+)?$/.test(s)) {
    // format US: 1,600 atau 1,600.50
    s = s.replace(/,/g, '');
  } else if (/^\d+,\d+$/.test(s)) {
    // desimal koma: 1795,5
    s = s.replace(',', '.');
  }

  const n = Number(s);
  if (isNaN(n) || !isFinite(n))
    return { error: 'harga_invalid', message: 'Harga bukan angka' };
  if (n <= 0)
    return { error: 'harga_invalid', message: 'Harga harus lebih dari 0' };
  return { value: n };
};

// Hitung harga jual: harga dasar + markup%, lalu dibulatkan ke kelipatan "step"
// Memakai aritmetika basis-poin agar tidak ada selisih floating point.
// Contoh: 1795 x 2,5% = 1839,875 -> 1.840
const calcSell = (base, markupPct, step) => {
  const bp = Math.round(markupPct * 100);
  const raw = (base * (10000 + bp)) / 10000;
  const s = step > 0 ? step : 1;
  return Math.round(raw / s + 1e-9) * s;
};

// Urutan: harga jual termurah -> termahal.
// Jika harga sama, urut berdasarkan jumlah Diamond, lalu kode produk.
// Baris tanpa harga jual (error) selalu di paling bawah.
const compareByPrice = (a, b) => {
  const pa = a.sell === null || a.sell === undefined ? Infinity : a.sell;
  const pb = b.sell === null || b.sell === undefined ? Infinity : b.sell;
  if (pa !== pb) return pa < pb ? -1 : 1;
  return (
    (a.diamond ?? Infinity) - (b.diamond ?? Infinity) ||
    String(a.code).localeCompare(String(b.code), 'en', { numeric: true })
  );
};

// Susun teks broadcast Telegram (monospace, rata kanan)
const buildTelegramText = (game, validRows, sortByPrice, codeBlock) => {
  if (!validRows.length) return '';

  const rows = [...validRows];
  if (sortByPrice) rows.sort(compareByPrice);

  const codeW = Math.max(...rows.map((r) => r.code.length));
  const diaW = Math.max(...rows.map((r) => String(r.diamond).length));
  const priceW = Math.max(...rows.map((r) => formatRupiah(r.sell).length));

  const lines = rows.map(
    (r) =>
      `${r.code.padEnd(codeW, ' ')}  ${String(r.diamond).padStart(
        diaW,
        ' '
      )} ${game.unit}  ${formatRupiah(r.sell).padStart(priceW, ' ')}`
  );

  const width = Math.max(game.title.length, ...lines.map((l) => l.length));
  const text = `${game.title}\n${'='.repeat(width)}\n\n${lines.join('\n')}`;

  return codeBlock ? '```\n' + text + '\n```' : text;
};

const copyToClipboard = async (text) => {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch (e) {
    // lanjut ke fallback
  }
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand('copy');
    document.body.removeChild(ta);
    return ok;
  } catch (e) {
    return false;
  }
};

// Baca file Excel/CSV -> daftar baris { line, code, price }
const readSheetFile = (file, onProgress) =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onprogress = (e) => {
      if (e.lengthComputable) onProgress(Math.round((e.loaded / e.total) * 60));
    };
    reader.onerror = () => reject(new Error('File tidak dapat dibaca.'));
    reader.onload = (e) => {
      try {
        onProgress(75);
        const wb = XLSX.read(new Uint8Array(e.target.result), {
          type: 'array',
        });
        if (!wb.SheetNames.length) {
          reject(new Error('Format Excel salah: file tidak memiliki sheet.'));
          return;
        }
        const ws = wb.Sheets[wb.SheetNames[0]];
        const matrix = XLSX.utils.sheet_to_json(ws, {
          header: 1,
          defval: '',
          raw: true,
        });

        const nonEmpty = matrix.filter((r) =>
          r.some((c) => String(c).trim() !== '')
        );
        if (!nonEmpty.length) {
          reject(new Error('File Excel kosong. Tidak ada data yang dibaca.'));
          return;
        }

        // Deteksi kolom lewat header; jika tidak ada pakai kolom 1 (kode) & 2 (harga)
        const first = matrix[0] || [];
        const norm = first.map((c) => String(c).trim().toLowerCase());
        let codeIdx = norm.findIndex((h) => CODE_HEADERS.includes(h));
        let priceIdx = PRICE_HEADERS.map((h) => norm.indexOf(h)).find(
          (i) => i >= 0
        );
        if (priceIdx === undefined) priceIdx = -1;
        // Kolom opsional (format Digiflazz buyer): Produk & Status
        const nameIdx = norm.findIndex((h) => NAME_HEADERS.includes(h));
        const statusIdx = norm.findIndex((h) => STATUS_HEADERS.includes(h));
        let start = 0;

        if (codeIdx >= 0 && priceIdx >= 0) {
          start = 1;
        } else {
          codeIdx = 0;
          priceIdx = 1;
          const firstCode = normCode(first[0]);
          const looksLikeCode = GAME_ORDER.some((id) =>
            GAME_CONFIG[id].codePattern.test(firstCode)
          );
          if (
            !looksLikeCode &&
            !isBlank(first[1]) &&
            parsePrice(first[1]).error
          ) {
            start = 1; // baris pertama dianggap judul kolom
          }
        }

        const rows = [];
        for (let i = start; i < matrix.length; i++) {
          const r = matrix[i];
          rows.push({
            line: i + 1,
            code: r[codeIdx],
            price: r[priceIdx],
            name: nameIdx >= 0 ? r[nameIdx] : '',
            status: statusIdx >= 0 ? r[statusIdx] : '',
          });
        }

        const hasAny = rows.some((r) => !isBlank(r.code) || !isBlank(r.price));
        if (!hasAny) {
          reject(
            new Error(
              'Format Excel salah: tidak ada data. Gunakan kolom "Kode Produk" dan "Harga".'
            )
          );
          return;
        }

        const maxCols = Math.max(...nonEmpty.map((r) => r.length));
        if (maxCols < 2) {
          reject(
            new Error(
              'Format Excel salah: dibutuhkan 2 kolom, yaitu "Kode Produk" dan "Harga".'
            )
          );
          return;
        }

        onProgress(90);
        resolve(rows);
      } catch (err) {
        reject(new Error('Format Excel salah: file tidak dapat diproses.'));
      }
    };

    reader.readAsArrayBuffer(file);
  });

// Default penerapan harga bila prop onApply tidak diberikan:
// disimpan ke localStorage. Sambungkan ke API/database Anda lewat prop onApply.
const defaultApply = async (payload) => {
  let current = {};
  try {
    current = JSON.parse(localStorage.getItem(PRICES_KEY) || '{}');
  } catch (e) {
    current = {};
  }
  const now = new Date().toISOString();
  payload.items.forEach((item) => {
    current[item.code] = {
      game: payload.game,
      diamond: item.diamond,
      supplierPrice: item.supplierPrice,
      sellPrice: item.sellPrice,
      markupPercent: payload.markupPercent,
      updatedAt: now,
    };
  });
  localStorage.setItem(PRICES_KEY, JSON.stringify(current));
};

const loadSettings = () => {
  const base = {
    markups: {},
    roundStep: 1,
    codeBlock: true,
    sort: true,
    ffSource: 'hpp',
  };
  GAME_ORDER.forEach((id) => {
    base.markups[id] = String(GAME_CONFIG[id].defaultMarkup).replace('.', ',');
  });
  try {
    const saved = JSON.parse(localStorage.getItem(SETTINGS_KEY) || 'null');
    if (saved && typeof saved === 'object') {
      return {
        markups: { ...base.markups, ...(saved.markups || {}) },
        roundStep: saved.roundStep || base.roundStep,
        codeBlock:
          typeof saved.codeBlock === 'boolean'
            ? saved.codeBlock
            : base.codeBlock,
        sort: typeof saved.sort === 'boolean' ? saved.sort : base.sort,
        ffSource: saved.ffSource === 'markup' ? 'markup' : 'hpp',
      };
    }
  } catch (e) {
    // abaikan
  }
  return base;
};

