const TPL_STYLES = `
  @keyframes tpl-rise { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
  @keyframes tpl-line { from { opacity: 0; transform: translateX(-8px); } to { opacity: 1; transform: none; } }
  @keyframes tpl-draw { to { stroke-dashoffset: 0; } }
  @keyframes tpl-pop { 0% { transform: scale(.55); opacity: 0; } 70% { transform: scale(1.1); opacity: 1; } 100% { transform: scale(1); opacity: 1; } }
  @keyframes tpl-ring { 0% { box-shadow: 0 0 0 0 rgba(79,70,229,.38); } 100% { box-shadow: 0 0 0 12px rgba(79,70,229,0); } }
  @keyframes tpl-ready { 0% { box-shadow: 0 0 0 0 rgba(16,185,129,.5); } 100% { box-shadow: 0 0 0 16px rgba(16,185,129,0); } }
  @keyframes tpl-sheen { from { transform: translateX(-130%); } to { transform: translateX(330%); } }
  @keyframes tpl-blink { 50% { opacity: 0; } }
  @keyframes tpl-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-5px); } }

  .tpl-rise { animation: tpl-rise .45s cubic-bezier(.2,.7,.2,1) both; }
  .tpl-line { animation: tpl-line .32s ease both; }
  .tpl-pop { animation: tpl-pop .4s ease both; }
  .tpl-draw { stroke-dasharray: 26; stroke-dashoffset: 26; animation: tpl-draw .45s .1s ease forwards; }
  .tpl-ring { animation: tpl-ring 1.6s ease-out infinite; }
  .tpl-ready { animation: tpl-ready 1.3s ease-out 2; }
  .tpl-caret { animation: tpl-blink 1s steps(1) infinite; }
  .tpl-float { animation: tpl-float 3.2s ease-in-out infinite; }

  .tpl-sheen { position: relative; overflow: hidden; }
  .tpl-sheen::after {
    content: ''; position: absolute; top: 0; bottom: 0; left: 0; width: 30%;
    background: linear-gradient(90deg, transparent, rgba(255,255,255,.35), transparent);
    transform: translateX(-130%); pointer-events: none;
  }
  .tpl-sheen:not(:disabled):hover::after { animation: tpl-sheen .8s ease; }

  .tpl-scroll::-webkit-scrollbar { width: 8px; height: 8px; }
  .tpl-scroll::-webkit-scrollbar-thumb { background: rgba(148,163,184,.35); border-radius: 8px; }
  .tpl-scroll::-webkit-scrollbar-thumb:hover { background: rgba(148,163,184,.6); }

  @media (prefers-reduced-motion: reduce) {
    .tpl-rise, .tpl-line, .tpl-pop, .tpl-ring, .tpl-ready, .tpl-caret, .tpl-float { animation: none !important; }
    .tpl-draw { animation: none !important; stroke-dashoffset: 0; }
    .tpl-sheen::after { display: none; }
  }
`;

