// Hitung naik secara halus dari nilai lama ke nilai baru
const useCountUp = (target, duration = 650) => {
  const [value, setValue] = useState(target);
  const shown = useRef(target);

  useEffect(() => {
    const reduce =
      typeof window !== 'undefined' &&
      window.matchMedia &&
      window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    if (reduce || shown.current === target) {
      shown.current = target;
      setValue(target);
      return undefined;
    }

    const from = shown.current;
    const start = performance.now();
    let raf;

    const tick = (now) => {
      const p = Math.min(1, (now - start) / duration);
      const eased = 1 - Math.pow(1 - p, 3);
      const next = Math.round(from + (target - from) * eased);
      shown.current = next;
      setValue(next);
      if (p < 1) raf = requestAnimationFrame(tick);
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target, duration]);

  return value;
};

const StatTile = ({ label, value, prefix = '', empty }) => {
  const shown = useCountUp(value || 0);
  return (
    <div className="rounded-xl border border-slate-200 bg-white px-3.5 py-3">
      <div className="text-[11px] font-medium text-slate-500">{label}</div>
      <div className="mt-0.5 text-lg font-black tabular-nums text-slate-900">
        {empty ? '-' : `${prefix}${formatRupiah(shown)}`}
      </div>
    </div>
  );
};

// Susun daftar harga -> { text, items, skipped }
// items: [{ sku, price }]  (dipakai juga untuk template Digiflazz)
const buildTemplateData = (rawRows, { title, prefix, sortByPrice }) => {
  const items = [];
  const skipped = [];
  const seen = new Set();

  rawRows.forEach((r) => {
    const code = normCode(r.code);
    if (!code && isBlank(r.price)) return; // baris kosong

    if (!code) {
      skipped.push({ label: `Baris ${r.line}`, reason: 'kode produk kosong' });
      return;
    }
    const p = parsePrice(r.price);
    if (p.error) {
      skipped.push({ label: code, reason: p.message.toLowerCase() });
      return;
    }
    if (seen.has(code)) {
      skipped.push({
        label: code,
        reason: 'kode duplikat (yang dipakai baris pertama)',
      });
      return;
    }
    seen.add(code);
    items.push({ sku: code, price: Math.max(1, Math.round(p.value)) });
  });

  if (sortByPrice) {
    items.sort(
      (a, b) =>
        a.price - b.price ||
        a.sku.localeCompare(b.sku, 'en', { numeric: true })
    );
  }

  if (!items.length) return { text: '', items, skipped };

  const prices = items.map((i) => formatRupiah(i.price));
  const codeW = Math.max(...items.map((i) => i.sku.length));
  const priceW = Math.max(...prices.map((p) => p.length));
  const lines = items.map(
    (it, i) => `${it.sku.padEnd(codeW, ' ')}  ${prices[i].padStart(priceW, ' ')}`
  );
  const lineW = Math.max(...lines.map((l) => l.length));

  let text = '';
  if (prefix === 'TURUN') text += 'INFO: TURUN HARGA\n\n';
  else if (prefix === 'NAIK') text += 'INFO: NAIK HARGA\n\n';
  if (title) text += `${title}\n${'═'.repeat(Math.max(title.length, lineW))}\n\n`;
  text += lines.join('\n');

  return { text, items, skipped };
};

