const TelegramUpload = ({ products, onApply }) => {
  // ==========================================
  // STATE
  // ==========================================
  const [activeTab, setActiveTab] = useState('telegram');

  // Pengaturan tampilan
  const [categoryName, setCategoryName] = useState('');
  const [prefixCaption, setPrefixCaption] = useState('NONE');
  const [sortByPrice, setSortByPrice] = useState(true);

  // Sumber data
  const [inputText, setInputText] = useState('');
  const [sourceRows, setSourceRows] = useState([]); // [{ line, code, price }]
  const [sourceLabel, setSourceLabel] = useState('');
  const [genId, setGenId] = useState(0); // naik tiap data baru (memicu animasi baris)
  const [reading, setReading] = useState({ active: false, progress: 0 });
  const [inputError, setInputError] = useState('');

  // Progres panduan & notifikasi
  const [copied, setCopied] = useState(false);
  const [didCopy, setDidCopy] = useState(false);
  const [didDownload, setDidDownload] = useState(false);
  const [toast, setToast] = useState('');

  // Hasil format dihitung otomatis: ubah judul/caption/urutan langsung tampil
  const { text: outputText, items, skipped } = useMemo(
    () =>
      buildTemplateData(sourceRows, {
        title: categoryName,
        prefix: prefixCaption,
        sortByPrice,
      }),
    [sourceRows, categoryName, prefixCaption, sortByPrice]
  );

  const hasData = items.length > 0;

  // Notifikasi & status tombol salin hilang otomatis
  useEffect(() => {
    if (!copied) return undefined;
    const t = setTimeout(() => setCopied(false), 2000);
    return () => clearTimeout(t);
  }, [copied]);

  useEffect(() => {
    if (!toast) return undefined;
    const t = setTimeout(() => setToast(''), 2400);
    return () => clearTimeout(t);
  }, [toast]);

  // ==========================================
  // HANDLER
  // ==========================================
  const loadRows = (rows, label) => {
    setSourceRows(rows);
    setSourceLabel(label);
    setGenId((g) => g + 1);
    setDidCopy(false);
    setDidDownload(false);
    setInputError('');
  };

  const handleFile = async (file) => {
    if (!file) return;
    setInputError('');

    if (!/\.(xlsx|xls|csv)$/i.test(file.name)) {
      setInputError(
        'Format file salah. Gunakan file Excel (.xlsx / .xls) atau .csv.'
      );
      return;
    }
    if (file.size > MAX_FILE_SIZE) {
      setInputError('Ukuran file terlalu besar (maksimal 5 MB).');
      return;
    }

    setReading({ active: true, progress: 5 });
    try {
      const rows = await readSheetFile(file, (p) =>
        setReading({ active: true, progress: p })
      );
      setReading({ active: true, progress: 100 });
      await delay(300);
      loadRows(rows, file.name);
    } catch (err) {
      setInputError(err.message || 'File tidak dapat diproses.');
    } finally {
      setReading({ active: false, progress: 0 });
    }
  };

  const handleGenerateText = () => {
    if (!inputText.trim()) {
      setInputError('Isi dulu datanya. Format: KODE HARGA, satu produk per baris.');
      return;
    }
    const rows = inputText.split('\n').map((line, i) => {
      const parts = line.trim().split(/\s+/);
      return { line: i + 1, code: parts[0], price: parts.slice(1).join('') };
    });
    loadRows(rows, 'Teks manual');
  };

  const handleLoadSample = () => {
    setInputText(TPL_SAMPLE_TEXT);
    setInputError('');
  };

  const handleReset = () => {
    setInputText('');
    setSourceRows([]);
    setSourceLabel('');
    setInputError('');
    setCopied(false);
    setDidCopy(false);
    setDidDownload(false);
  };

  const handleCopy = async () => {
    if (!outputText) return;
    const ok = await copyToClipboard(outputText);
    if (ok) {
      setCopied(true);
      setDidCopy(true);
      setToast('Berhasil disalin ke clipboard');
    } else {
      setInputError('Gagal menyalin. Blok teks di preview lalu salin manual.');
    }
  };

  // Unduh template Excel untuk update harga di Digiflazz
  const handleDownloadDigiflazzTemplate = () => {
    if (!items.length) return;

    const data = [
      ['Buyer SKU Code', 'Harga Baru / Margin'],
      ...items.map((item) => [item.sku, item.price]),
    ];
    const ws = XLSX.utils.aoa_to_sheet(data);
    ws['!cols'] = [{ wch: 25 }, { wch: 20 }];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Update Harga Digiflazz');

    const fileName = `Template_Update_Harga_Digiflazz_${
      categoryName.replace(/\s+/g, '_') || 'Produk'
    }.xlsx`;
    XLSX.writeFile(wb, fileName);

    setDidDownload(true);
    setToast('Template Digiflazz berhasil diunduh');
  };

  // ==========================================
  // RENDER
  // ==========================================
  const tabClass = (id) =>
    `text-xs font-bold px-4 py-2 rounded-lg transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-indigo-500 ${
      activeTab === id
        ? 'bg-white text-slate-900 shadow-sm'
        : 'text-slate-500 hover:text-slate-700'
    }`;

  return (
    <>
      {/* Pengalih tab */}
      <div className="max-w-5xl mx-auto px-4 sm:px-6 pt-4 sm:pt-6 font-sans">
        <div
          role="tablist"
          className="inline-flex gap-1 p-1 bg-slate-100 rounded-xl border border-slate-200/80"
        >
          <button
            role="tab"
            aria-selected={activeTab === 'telegram'}
            onClick={() => setActiveTab('telegram')}
            className={tabClass('telegram')}
          >
            Template Harga Digiflazz
          </button>
          <button
            role="tab"
            aria-selected={activeTab === 'game'}
            onClick={() => setActiveTab('game')}
            className={tabClass('game')}
          >
            Update Harga Game
          </button>
        </div>
      </div>

      {activeTab === 'game' ? (
        <GamePriceUpdate products={products} onApply={onApply} />
      ) : (
        <DigiflazzTemplatePanel
          categoryName={categoryName}
          setCategoryName={setCategoryName}
          prefixCaption={prefixCaption}
          setPrefixCaption={setPrefixCaption}
          sortByPrice={sortByPrice}
          setSortByPrice={setSortByPrice}
          inputText={inputText}
          setInputText={setInputText}
          onGenerateText={handleGenerateText}
          onLoadSample={handleLoadSample}
          sourceLabel={sourceLabel}
          reading={reading}
          inputError={inputError}
          onFile={handleFile}
          outputText={outputText}
          items={items}
          skipped={skipped}
          genId={genId}
          copied={copied}
          onCopy={handleCopy}
          onDownload={handleDownloadDigiflazzTemplate}
          onReset={handleReset}
          stepsDone={[hasData, didCopy, didDownload]}
        />
      )}

      {/* Notifikasi */}
      <div aria-live="polite" className="pointer-events-none">
        {toast && (
          <div className="tpl-pop fixed bottom-6 right-6 z-50 flex items-center gap-2.5 rounded-xl border border-emerald-500 bg-emerald-600 px-4 py-3 text-xs font-semibold text-white shadow-2xl">
            <Icon d={ICONS.check} className="w-4 h-4" sw={2.5} />
            <span>{toast}</span>
          </div>
        )}
      </div>
    </>
  );
};

export default TelegramUpload;